Certainly! Here’s a concise Node.js application implementing a CRUD REST API to manage employee data. This example uses Express for routing and an in-memory array to store employee records for simplicity.

---

**1. Initialization and Setup**

First, set up your project:

```bash
mkdir employee-api
cd employee-api
npm init -y
npm install express body-parser
```

---

**2. Create `app.js`**

```javascript
const express = require('express');
const bodyParser = require('body-parser');

const app = express();
app.use(bodyParser.json());

let employees = [];
let nextId = 1;

// Create employee
app.post('/employees', (req, res) => {
    const { name, role, email } = req.body;
    if (!name || !role || !email) {
        return res.status(400).json({ error: 'Name, role, and email are required.' });
    }
    const newEmployee = { id: nextId++, name, role, email };
    employees.push(newEmployee);
    res.status(201).json(newEmployee);
});

// Get all employees
app.get('/employees', (req, res) => {
    res.json(employees);
});

// Get single employee by ID
app.get('/employees/:id', (req, res) => {
    const id = parseInt(req.params.id);
    const employee = employees.find(emp => emp.id === id);
    if (!employee) {
        return res.status(404).json({ error: 'Employee not found.' });
    }
    res.json(employee);
});

// Update employee by ID
app.put('/employees/:id', (req, res) => {
    const id = parseInt(req.params.id);
    const { name, role, email } = req.body;
    const employee = employees.find(emp => emp.id === id);
    if (!employee) {
        return res.status(404).json({ error: 'Employee not found.' });
    }
    if (name) employee.name = name;
    if (role) employee.role = role;
    if (email) employee.email = email;
    res.json(employee);
});

// Delete employee by ID
app.delete('/employees/:id', (req, res) => {
    const id = parseInt(req.params.id);
    const index = employees.findIndex(emp => emp.id === id);
    if (index === -1) {
        return res.status(404).json({ error: 'Employee not found.' });
    }
    employees.splice(index, 1);
    res.status(204).send();
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Employee API listening on port ${PORT}`);
});
```

---

**3. Running the API**

```bash
node app.js
```

---

**Endpoints Overview**

- `POST /employees` — Create new employee (expects `{ name, role, email }`)
- `GET /employees` — Retrieve all employees
- `GET /employees/:id` — Retrieve single employee by ID
- `PUT /employees/:id` — Update existing employee (any of: `{ name, role, email }`)
- `DELETE /employees/:id` — Delete an employee by ID

---

This simple Node.js app provides a functional starting point for employee data management through a RESTful interface. For persistence, you might later swap out the in-memory array for a database.

