This example node simply sets `msg.payload` to a configurable message, defaulting to `"Hello from Pankaj!"`, each time it receives an input. You can further expand its functionality as needed.

Certainly! Here’s a Metal compute kernel in Metal Shading Language (MSL) that performs a Gaussian blur on a 2D image. The kernel safely handles boundary conditions, ensuring it never reads out-of-bounds texels.

**Kernel Code:**

```metal
#include <metal_stdlib>
using namespace metal;

// Constants for kernel (can be set from CPU side)
constant int KERNEL_RADIUS [[function_constant(0)]];

// A 1D Gaussian kernel provided as a buffer
kernel void gaussianBlur(
    texture2d<float, access::read>  inTexture  [[texture(0)]],
    texture2d<float, access::write> outTexture [[texture(1)]],
    constant float *                kernel     [[buffer(0)]],
    uint2 tid [[thread_position_in_grid]])
{
    // Get image size
    uint width  = inTexture.get_width();
    uint height = inTexture.get_height();

    if (tid.x >= width || tid.y >= height) return; // Guard threads outside image

    float4 color = float4(0.0);
    float  sum   = 0.0;

    // Iterate over the kernel window
    for (int ky = -KERNEL_RADIUS; ky <= KERNEL_RADIUS; ++ky) {
        for (int kx = -KERNEL_RADIUS; kx <= KERNEL_RADIUS; ++kx) {

            // Compute clamped coordinates to stay within bounds
            int2 coord = int2(tid) + int2(kx, ky);
            coord.x = clamp(coord.x, 0, int(width) - 1);
            coord.y = clamp(coord.y, 0, int(height) - 1);

            // Read texel, fetch kernel coefficient
            float4 sample = inTexture.read(uint2(coord));
            float weight = kernel[(ky + KERNEL_RADIUS) * (2 * KERNEL_RADIUS + 1) + (kx + KERNEL_RADIUS)];
            color += sample * weight;
            sum += weight;
        }
    }

    // Normalize the result
    outTexture.write(color / sum, tid);
}
```

---

**How out-of-bounds memory errors are avoided:**

- **Clamping Coordinates:**  
  When iterating over neighboring pixels in the kernel window, pixel coordinates are computed as `coord = tid + kx, ky`. If these coordinates would fall outside the image (e.g., negative indices, or indices past the width/height), they are clamped:
  ```metal
  coord.x = clamp(coord.x, 0, int(width) - 1);
  coord.y = clamp(coord.y, 0, int(height) - 1);
  ```
  This ensures that every access to `inTexture.read(uint2(coord))` is within valid texture bounds.

- **Guarding Out-of-Bounds Threads:**  
  The first conditional in the kernel:
  ```metal
  if (tid.x >= width || tid.y >= height) return;
  ```
  prevents any thread from accessing memory outside the bounds if the dispatch covered more threads than needed.

**Result:**  
All memory reads and writes are performed within valid image data; there are no out-of-bounds accesses, preventing memory errors or undefined behavior.

To create a Terraform module that provisions an AWS API Gateway (REST API) capable of accepting a POST request and pushing the received data directly into DynamoDB, you’ll need to use AWS service integrations. Specifically, you would create an API Gateway REST API with a POST method backed by an AWS service integration pointing to DynamoDB's `PutItem` action.

Below is a simplified example of a Terraform module implementing this pattern. It creates:

- A DynamoDB table
- An IAM role and policy allowing API Gateway to write to DynamoDB
- An API Gateway REST API with a POST resource, integrated with DynamoDB via a "AWS Service Proxy" integration

**Module Structure:**
```
api-gw-to-dynamodb/
├── main.tf
├── outputs.tf
├── variables.tf
```

---

### `variables.tf`
```hcl
variable "table_name" {
  description = "Name of the DynamoDB table"
  type        = string
}

variable "hash_key" {
  description = "Partition key attribute name"
  type        = string
  default     = "id"
}

variable "hash_key_type" {
  description = "Type for partition key"
  type        = string
  default     = "S"
}
```

---

### `main.tf`
```hcl
resource "aws_dynamodb_table" "this" {
  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"

  hash_key     = var.hash_key

  attribute {
    name = var.hash_key
    type = var.hash_key_type
  }
}

resource "aws_iam_role" "apigw_role" {
  name = "${var.table_name}-apigw-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "apigateway.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "apigw_policy" {
  name = "${var.table_name}-apigw-policy"
  role = aws_iam_role.apigw_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = "dynamodb:PutItem"
      Resource = aws_dynamodb_table.this.arn
    }]
  })
}

resource "aws_api_gateway_rest_api" "this" {
  name        = "${var.table_name}-api"
  description = "API Gateway frontend for DynamoDB"
}

resource "aws_api_gateway_resource" "items" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_rest_api.this.root_resource_id
  path_part   = "items"
}

resource "aws_api_gateway_method" "post_items" {
  rest_api_id   = aws_api_gateway_rest_api.this.id
  resource_id   = aws_api_gateway_resource.items.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "dynamodb" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.items.id
  http_method = aws_api_gateway_method.post_items.http_method
  type        = "AWS"
  integration_http_method = "POST"
  uri         = "arn:aws:apigateway:${var.aws_region}:dynamodb:action/PutItem"
  credentials = aws_iam_role.apigw_role.arn
  request_templates = {
    "application/json" = <<EOF
{
    "TableName": "${aws_dynamodb_table.this.name}",
    "Item": {
        "${var.hash_key}": {
            "S": "$input.path('$.${var.hash_key}')"
        }
        #foreach($key in $input.path('$').keySet())
        #if($key != "${var.hash_key}")
        ,"$key": {"S": "$input.path('$.${key}')"}
        #end
        #end
    }
}
EOF
  }
}

resource "aws_api_gateway_method_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.items.id
  http_method = aws_api_gateway_method.post_items.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
