**React Hook Template for Connecting to a GraphQL API Backend**

```jsx
import { useState, useEffect } from 'react';

function useGraphQL(query, variables = {}) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let isMounted = true; // Prevent state updates if unmounted

    async function fetchData() {
      setLoading(true);
      try {
        const response = await fetch('https://your-graphql-endpoint.com/graphql', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            // Add any auth headers here
          },
          body: JSON.stringify({ query, variables }),
        });
        const result = await response.json();
        if (isMounted) {
          setData(result.data);
          setError(result.errors || null);
        }
      } catch (err) {
        if (isMounted) {
          setError(err);
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    }

    fetchData();

    return () => {
      isMounted = false;
    };
  }, [query, JSON.stringify(variables)]);

  return { data, loading, error };
}

export default useGraphQL;
```

