using UnityEditor;
using UnityEngine;
using UnityEditor.SceneManagement;
using System.Collections.Generic;

public class AudioSourceLister : EditorWindow
{
    // Store found AudioSources
    private List<AudioSource> audioSources = new List<AudioSource>();
    // For scrollbar position
    private Vector2 scrollPos;

    // Add menu item to open the window
    [MenuItem("Tools/AudioSource Lister")]
    public static void ShowWindow()
    {
        GetWindow<AudioSourceLister>("AudioSource Lister");
    }

    private void OnFocus()
    {
        // Refresh whenever this window gains focus
        RefreshAudioSourceList();
    }

    void OnGUI()
    {
        // Button to refresh list manually
        if (GUILayout.Button("Refresh Audio Source List"))
        {
            RefreshAudioSourceList();
        }

        EditorGUILayout.Space();
        EditorGUILayout.LabelField("AudioSources in Scene", EditorStyles.boldLabel);

        // Begin scroll view for potentially long lists
        scrollPos = EditorGUILayout.BeginScrollView(scrollPos);

        if (audioSources.Count == 0)
        {
            EditorGUILayout.LabelField("No AudioSources found.");
        }
        else
        {
            foreach (var src in audioSources)
            {
                if (src == null) continue; // Object may have been deleted

                EditorGUILayout.BeginHorizontal();
                // Show the GameObject name
                EditorGUILayout.ObjectField(src.gameObject.name, src, typeof(AudioSource), true);

                // Play button, only enabled in Editor if not already playing
                GUI.enabled = !src.isPlaying && !Application.isPlaying;
                if (GUILayout.Button("Play", GUILayout.Width(60)))
                {
                    // Play the AudioSource in the Editor
                    PlayClipInEditor(src);
                }
                GUI.enabled = true;

                EditorGUILayout.EndHorizontal();
            }
        }
        EditorGUILayout.EndScrollView();
    }

    // Refresh the list of AudioSources from the current scene
    private void RefreshAudioSourceList()
    {
        // Find all AudioSources, even if they're disabled
        audioSources = new List<AudioSource>(Resources.FindObjectsOfTypeAll<AudioSource>());

        // Filter to objects in the current scene, exclude prefabs/assets
        audioSources.RemoveAll(src =>
            EditorUtility.IsPersistent(src.gameObject) ||
            !(src.gameObject.hideFlags == HideFlags.None || src.gameObject.hideFlags == HideFlags.HideInHierarchy)
        );
    }

    // Play AudioClip in the editor for previewing (does not require play mode)
    private void PlayClipInEditor(AudioSource src)
    {
        if (src.clip != null)
        {
            // Method in UnityEditor to play AudioClip
            // Stop any currently playing clips first
            UnityEditor.EditorUtility.PlayClip(src.clip);
        }
        else
        {
            Debug.LogWarning($"AudioSource on {src.gameObject.name} has no clip assigned.");
        }
    }
}
```

Certainly. Below is a basic Node.js application for a CRUD REST API to manage employee data. This example uses **Express** as the web framework and **in-memory storage** for simplicity.

---

**1. Initialize the Project**

```bash
npm init -y
npm install express
```

---

**2. Create `app.js`**

```js
const express = require('express');
const app = express();
const port = 3000;

app.use(express.json());

// In-memory data store
let employees = [];
let nextId = 1;

// CREATE - Add a new employee
app.post('/employees', (req, res) => {
    const { name, role, email } = req.body;
    if (!name || !role || !email) {
        return res.status(400).json({ error: 'Missing required fields.' });
    }
    const employee = { id: nextId++, name, role, email };
    employees.push(employee);
    res.status(201).json(employee);
});

// READ - Get all employees
app.get('/employees', (req, res) => {
    res.json(employees);
});

// READ - Get a single employee by ID
app.get('/employees/:id', (req, res) => {
    const id = parseInt(req.params.id);
    const employee = employees.find(emp => emp.id === id);
    if (!employee) {
        return res.status(404).json({ error: 'Employee not found.' });
    }
    res.json(employee);
});

// UPDATE - Update an employee by ID
app.put('/employees/:id', (req, res) => {
    const id = parseInt(req.params.id);
    const employee = employees.find(emp => emp.id === id);
    if (!employee) {
        return res.status(404).json({ error: 'Employee not found.' });
    }
    const { name, role, email } = req.body;
    if (name) employee.name = name;
    if (role) employee.role = role;
    if (email) employee.email = email;
    res.json(employee);
});

// DELETE - Remove an employee by ID
app.delete('/employees/:id', (req, res) => {
    const id = parseInt(req.params.id);
    const index = employees.findIndex(emp => emp.id === id);
    if (index === -1) {
        return res.status(404).json({ error: 'Employee not found.' });
    }
    employees.splice(index, 1);
    res.json({ message: 'Employee deleted.' });
});

app.listen(port, () => {
    console.log(`Employee API running at http://localhost:${port}`);
});
```

---

**3. Start your API**

```bash
node app.js
```
Your API will now run at [http://localhost:3000](http://localhost:3000).

---

**Sample API endpoints:**

- `POST /employees` - Add new employee (JSON: `{ "name": "", "role": "", "email": "" }`)
- `GET /employees` - List all employees
- `GET /employees/:id` - Get employee by ID
- `PUT /employees/:id` - Update employee by ID
- `DELETE /employees/:id` - Delete employee by ID

---

This setup is well-suited for quick development or demonstration purposes. For production, consider integrating with a real database and using environment variables for configuration.

