Outline:

1. **Initialize LLVM**: Set up the LLVM environment, including context, module, and builder.
2. **Define the Function Prototype**: Specify the signature for the `fib` function (`int fib(int n)`).
3. **Create Basic Blocks**: Structure the function with blocks for entry, base case (`n<=2`), and recursion (`fib(n-1) + fib(n-2)`).
4. **Generate IR for the Base Case**: If `n <= 2`, return 1.
5. **Generate IR for the Recursive Case**: Otherwise, compute and sum `fib(n-1)` and `fib(n-2)`.
6. **Verify the Function**: Use an LLVM utility to ensure the function is well-formed.
7. **Cleanup**: Properly dispose of all LLVM objects created.

**Sample Code Using LLVM-C API (in C):**

```c
#include <llvm-c/Core.h>
#include <llvm-c/Analysis.h>

int main() {
    LLVMModuleRef module = LLVMModuleCreateWithName("fib_module");
    LLVMContextRef context = LLVMGetGlobalContext();
    LLVMBuilderRef builder = LLVMCreateBuilder();

    // Step 1: Define the function prototype: int fib(int)
    LLVMTypeRef param_types[] = { LLVMInt32TypeInContext(context) };
    LLVMTypeRef ret_type = LLVMFunctionType(LLVMInt32TypeInContext(context), param_types, 1, 0);
    LLVMValueRef fib_func = LLVMAddFunction(module, "fib", ret_type);

    // Step 2: Create blocks for control flow
    LLVMBasicBlockRef entry = LLVMAppendBasicBlock(fib_func, "entry");
    LLVMBasicBlockRef recurse = LLVMAppendBasicBlock(fib_func, "recurse");
    LLVMBasicBlockRef basecase = LLVMAppendBasicBlock(fib_func, "basecase");

    LLVMPositionBuilderAtEnd(builder, entry);

    // Step 3: Get function argument (n)
    LLVMValueRef n = LLVMGetParam(fib_func, 0);

    // Step 4: if (n <= 2) goto basecase else goto recurse
    LLVMValueRef cond = LLVMBuildICmp(builder, LLVMIntSLE, n, LLVMConstInt(LLVMInt32TypeInContext(context), 2, 0), "cond");
    LLVMBuildCondBr(builder, cond, basecase, recurse);

    // Step 5: Base case: return 1
    LLVMPositionBuilderAtEnd(builder, basecase);
    LLVMBuildRet(builder, LLVMConstInt(LLVMInt32TypeInContext(context), 1, 0));

    // Step 6: Recursive case: return fib(n-1) + fib(n-2)
    LLVMPositionBuilderAtEnd(builder, recurse);
    LLVMValueRef n_minus_1 = LLVMBuildSub(builder, n, LLVMConstInt(LLVMInt32TypeInContext(context), 1, 0), "n_minus_1");
    LLVMValueRef n_minus_2 = LLVMBuildSub(builder, n, LLVMConstInt(LLVMInt32TypeInContext(context), 2, 0), "n_minus_2");

    LLVMValueRef args1[] = { n_minus_1 };
    LLVMValueRef args2[] = { n_minus_2 };

    LLVMValueRef call1 = LLVMBuildCall(builder, fib_func, args1, 1, "fib_n1");
    LLVMValueRef call2 = LLVMBuildCall(builder, fib_func, args2, 1, "fib_n2");

    LLVMValueRef sum = LLVMBuildAdd(builder, call1, call2, "sum");
    LLVMBuildRet(builder, sum);

    // Step 7: Verify and cleanup
    char *error = NULL;
    LLVMVerifyModule(module, LLVMAbortProcessAction, &error);
    LLVMDisposeMessage(error);

    // Optional: print
    LLVMPrintModuleToFile(module, "fib.ll", &error);

    LLVMDisposeBuilder(builder);
    LLVMDisposeModule(module);

    return 0;
}
```

**Good Coding Practices Illustrated:**

- Each LLVM construct (context, module, builder) is created and properly destroyed to avoid memory leaks.
- The function signature is clearly defined.
- Branching and block management is explicit for clarity.
- Meaningful variable names are used for clarity.
- Module verification ensures that the generated IR is valid.
- Printing to file enables inspection of LLVM IR.

**Note:**  
This code assumes you have the LLVM C library installed and correctly linked during compilation (`-lLLVM`). Adjustments may be necessary depending on your environment.

